        # A zero-filled instruction panel with sparse marks specifies
        # the color to fill the other panel.
        if set(left_values) == {0, 6}:
            return [[6 for _ in row] for row in right]

        counts = {v: right_values.count(v) for v in set(right_values)}
        minority = min(counts, key=counts.get)
